INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-ch19-andhra-mahasabha', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p1", "partName": "Background — Early Organizational Efforts", "bodyMd": "The roots of the Andhra Mahasabha lie in an incident of linguistic humiliation. In November 1921, a Nizam State Social Reformation meeting (Sanga Samskarana Mahasabha) was held at Vivekavardhini School, Hyderabad, under the chairmanship of D.K. Karvay. Speakers at this meeting addressed the audience in Urdu, Marathi, Kannada, and English. When the Hyderabad advocate **Aalampalli Venkat Rama Rao** attempted to speak in Telugu, Marathi and Kannada attendees opposed him and mocked him with whistles and jeers.\n\nThis humiliation became the spark for Telugu organization in the Nizam''s Dominions. Telugu people gathered at Tekumalla Rangarao''s house on 12 November 1921 and established the **Nizam State Jana Sangam** (Nizam Rashtra Andhra Jana Sangam). **Madapati Hanumanth Rao** played the leading role in its formation.\n\n*   The 1st meeting of the Nizam State Jana Sangam was held on 14 February 1922 at Reddy Hostel, Hyderabad, presided over by **Konda Venkat Ranga Reddy**.\n*   On 1 April 1923, representatives gathered at Hanumakonda and renamed the body the **Andhra Jana Kendra Sangam**, with **Barrister Raja Gopal Reddy** as its 1st President and Madapati Hanumanth Rao as its 1st Secretary.\n\n### Andhra Jana Kendra Sangam (1923)\n\n*   Its 1st meeting was held at Madapati Hanumanth Rao''s house in Hyderabad in July 1923, where **Rao Bahadur Venkat Reddy** was elected President.\n*   Its 2nd meeting was held in 1924 at the office of the _Nilgiri_ newspaper in Nalgonda, whose editor was Shabnavisu Venkat Narsimha Rao.\n\n**Activities:**\n\n*   Collection of palm-leaf manuscripts (Talapatra Grandham).\n*   Research into ancient history to highlight the greatness of the Andhra people.\n*   Establishment of libraries.\n*   Publication of pamphlets and books, including works campaigning against the _Sirbarahi_ system (the free supply of goods to visiting government officials), against _Vetti Chakiri_ (forced labour), and against the _Mohathurba Maggam_ tax imposed on weavers — the last of these covered in Mateti Papayya''s book _Mohathurba Maggam Pannu_.\n*   In 1930, a _Kakatiya Charcha Goshti_ (discussion meeting) was held at Warangal and the _Kakatiya Sanchika_ was published, which in turn carried _Andrula Sangika Charitra_ and Adiraju Veerabhadra Rao''s _Telangana Inscriptions_.\n*   Many Telugu-medium schools were founded under the Sangam''s auspices; in 1928 Madapati Hanumantha Rao established the Andhra Girls School.\n*   Adiraju Veerabhadra Rao founded the **Andhra Parishodaka Sangam** under the Kendra Sangam''s aegis (later renamed **Lakshman Raya Parishodana Mandali**) and collected numerous palm-leaf manuscripts and inscriptions.\n\nIn 1930, the Andhra Jana Kendra Sangam itself was renamed the **Nizam Rashtra Andhra Mahasabha** — Telangana''s first political organization.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p2", "partName": "Formation and Ground Rules of the Andhra Mahasabha", "bodyMd": "The Nizam government permitted the Andhra Mahasabha to be convened only under strict conditions: the presiding officer had to be a resident of Hyderabad State (not an \"outsider\"), nothing was to be said that would hurt the sentiments of other religious communities or cause insult, and no political matters were to be raised in the sabha.\n\nBetween 1930 and 1946, **13 sessions** of the Andhra Mahasabha were held. Alongside these, **Andhra Mahila Sabhas** (women''s sessions) were also convened, largely through the efforts of **Durgabhai Deshmukh**.\n\nThe overall purpose of these sessions was to build social and cultural awareness among the people. Madapati Hanumantha Rao regarded the Andhra Mahasabha as Telangana''s equivalent of the national Indian National Congress — just as the Congress represented the national movement for all Indians, the Andhra Mahasabha represented the movement (Andhrodyamam) for the Telugu people of Telangana.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p3", "partName": "First Andhra Mahasabha — Jogipet (1930)", "bodyMd": "The Andhrodyamam''s second phase began in 1930 when the first Andhra Mahasabha convened at **Jogipet**, in the Andole taluk of Medak district, with the merchants of Jogipet providing financial support for the session.\n\n*   **President:** Suravaram Pratapa Reddy (B.A., B.L.; editor of the _Golkonda Patrika_, prolific author, and a champion of the Telangana people).\n*   **President of the inaugural committee:** Tekumalla Ananta Venkat Rao (High Court lawyer).\n*   **President of the 1st Andhra Mahila Sabha:** Nadimpalli Sundaramma.\n\nThe session opened with the song \"Andhradesapu matti adi maku kanakamu\" (\"The soil of the Andhra land is gold to us\"), reflecting the movement''s early emphasis on cultural pride in Telugu identity. Madapati Hanumantha Rao and other leaders were careful to keep this pride from turning into arrogance toward other communities, since the movement in its first phase was chiefly focused on this cultural self-respect.\n\n**Resolutions of the Jogipet Sabha:**\n\n*   Repeal of **Gasthi Nishan–53**, an ordinance passed by the Nizam in 1926 banning public meetings and conferences.\n*   **Bhagya Reddy Varma** moved a resolution for the abolition of untouchability.\n*   The Nizam government should provide educational facilities for Adi-Hindus.\n*   Compulsory primary education should be introduced.\n*   Regional languages should be encouraged in state libraries.\n*   Child marriage should be discouraged, and widow remarriage encouraged.\n*   The government should depute veterinary doctors and agriculture department officials to raise awareness among the rural population (a request the Nizam government accepted).\n*   The Sabha also worked toward village reconstruction and resolving farmers'' problems.\n\nA parallel women''s session, the first Andhra Mahila Sabha, was held during the same days under Nadimpalli Sundaramma''s presidency, discussing the condition of ancient and contemporary women, marriage problems, chastity, widowhood, and the practice of concubinage.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p4", "partName": "Second Andhra Mahasabha — Devarakonda (1931)", "bodyMd": "The second Andhra Mahasabha was held at **Devarakonda**, Nalgonda district, from 3–5 March 1931.\n\n*   **President:** Burgula Ramakrishna Rao.\n*   **President of the Mahila Sabha:** T. Varalakshmi.\n*   **President of the inaugural committee:** Pulijala Venkat Ranga Rao.\n\n**Ravi Narayana Reddy** and fellow students of Reddy Hostel walked from Nizam College to Devarakonda to attend this session. Many delegates spoke in Telugu at this meeting — a direct result of the Andhra Mahasabha''s efforts to promote the Telugu language within Hyderabad State.\n\nBurgula Ramakrishna Rao belonged to a jagirdar family of Burgula village, Palamoor taluk, Mahbubnagar district. He trained as a lawyer in Pune, and it was during his student days there that his family surname came to be recorded as \"Rankinsonrao Burgula/Burgula Ramakrishna Rao.\" He went on to become Hyderabad State''s first Chief Minister after Independence, and was known as a scholar, poet, and author fluent in several languages.\n\nAt Devarakonda, Burgula took care that the session remain non-political and focused on people''s welfare and development. **Vaman Naik** attended and supported Andhra causes regardless of the movement involved, and donated to the Sarada Niketan in Guntur; he held somewhat orthodox views on religious and social questions, however, which limited his influence over the social resolutions passed earlier at Jogipet.\n\nAt the same Devarakonda session, **Arya Samaj** leader Keshavrao also attended and tried to advance social reform among the Andhras present. Burgula, as president, tactfully steered the session away from political speeches made by visiting Maharashtrian delegates.\n\n*   **Second Mahila Sabha:** presided over by Smt. T. Varalakshmamma. This sabha called for compulsory elementary education for women, higher education through the mother tongue, and training in medicine and the treatment of illnesses for women, and it discussed the beginnings of ministership for women.\n*   It also opposed the purdah system and called for reform of the practice of child marriage. Overall, the resolutions of this sabha were directed toward women''s advancement.\n\n**Bhagya Reddy Varma Resolution (Devarakonda):** A resolution was passed concerning untouchability and the _Vetti_ (forced labour) imposed on lower castes, calling for equal rights and respect for them.\n\nSessions were meant to be held annually, but after the second Devarakonda session it took **three years** for the third session to be convened, owing to delays in obtaining government permission.", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p5", "partName": "Third Andhra Mahasabha — Khammam Mettu (1934)", "bodyMd": "Background to the delay: nine months after the Devarakonda session, the organizing committee in Jatprole estate (Mahbubnagar district) began efforts to hold the third session at Pentlavalli village, led by the prominent lawyer Chakrapani Narasaraju. Since Jatprole was itself a samsthanam (estate), permission had to be obtained from the samsthanam''s own administration rather than directly from the Nizam government.\n\nWhen the organizers sought this permission, the samsthanam administration wrote back stating in writing that it did not have the authority to grant it, and referred the matter to the Nizam government.\n\n*   The invitee committee then approached the Mahbubnagar Collector, requesting that the state administration not interfere in the affairs of the samsthanam and that the same procedure followed for the Devarakonda sabha be applied here as well. The Collector agreed.\n*   The organizers also petitioned the Nizam Sarkar directly, and the matter eventually reached the Prime Minister, Maharaja Sir Kishan Pershad Bahadur. His reply stated that permission could not be granted either to hold the session in the samsthanam or elsewhere.\n*   Public dissatisfaction grew as an entire year passed without resolution, provoking questions about why a Collector''s permit should even be necessary for such a small matter, and whether it reflected excessive intolerance from a government with no regard for free speech.\n*   A fresh attempt to convene the session began on 2 March 1932. After repeated petitions, the Police Department minister Karnal Trench indicated the matter would be decided within six months, later postponing his reply further.\n*   Madapati Hanumantharao and Burgula Ramakrishnarao argued in this dispute that their movement was purely non-political, concerned only with libraries and the spread of knowledge, invoking the precedent of the library movement in Bengal, where such movements had been associated with revolutionary societies but were still permitted. \n\n*   They asked whether the government feared the community could not afford to pay a possible fine, and affirmed it was ready to bear whatever expense was needed to hold the sabha, since dropping it would lower the community''s standing in the eyes of the state''s people. Karnal Trench nonetheless refused permission.\n\n*   Permission was ultimately obtained only after community leaders accepted \"Bramhandam\" of government conditions in full.\n\nThe third Andhra Mahasabha was eventually held at **Khammam Mettu**, presided over by **Pulijala Rangarao**, a Nalgonda advocate. At this session, unlike earlier sessions, the government banned discussion of social issues altogether, permitting only non-political matters. The Collector repeatedly sent word to the presiding officers to keep proceedings within bounds even in the middle of the night while the session was underway.\n\nFaced with the choice of what to discuss if neither politics nor social reform were allowed, the leaders settled on **farmers'' problems**, and resolutions on agrarian issues were passed. It was at this third Mahasabha that farmers first gained real prominence in the movement, followed also by farm labourers.\n\n*   **Third Andhra Mahila Sabha:** presided over by Smt. Ellapragada Seetakumari.\n\nBeyond the farmers'' resolutions, the third Mahasabha also passed resolutions on the eradication of the Devadasi and Begar systems, strengthening the education system, extending the benefits of the postal system to the public, and using the religious cess collected from merchants and businessmen to fund primary education.", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p6", "partName": "Fourth Andhra Mahasabha — Sircilla (1935)", "bodyMd": "The fourth Andhra Mahasabha was held in **Sircilla**, Karimnagar district, from 26–28 January 1935, under the presidency of **Madapati Hanumantha Rao**; his wife, **Madapati Manikyamma**, presided over the accompanying Mahila Sabha.\n\n*   Delegates at Sircilla made a special effort to encourage speaking in Telugu, and pride in the Telugu language and culture found renewed encouragement at this session.\n*   It was at this Sircilla session that the Andhra Mahasabha itself adopted a formal set of rules (niyamavali) for the organization, incorporating the aspirations of the youth alongside the movement''s existing goals.\n*   Resolutions passed here (12 in total, including amendments to the Andhra Mahasabha''s own rules) covered: promotion of education, compulsory primary education, higher education for Andhra girls through the mother tongue, abolition of child marriage, protection of the rights of jagir tenants, village reconstruction, facilities for farmers, relief for indebted farmers, local self-government, and the upliftment of depressed classes.\n*   Six months after the Sircilla session, Hanumantha Rao met the government''s Propaganda Department chief Aliyawar Jung to press the demand that Andhra-majority districts in the state be merged with the Andhra districts of Madras. The government replied that it suspected this demand actually aimed at merging all Andhra districts of the state with those of Madras, and Hanumantha Rao expressed doubt about how the matter had reached the political department.\n*   The leaders, however, denied that this had ever been the movement''s actual objective, and the government dismissed the demand as constitutionally untenable.", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p7", "partName": "Fifth Andhra Mahasabha — Shadnagar (1936)", "bodyMd": "The fifth Andhra Mahasabha was held at **Shadnagar** in 1936, under the presidency of **Konda Venkata Ranga Reddy**.\n\n*   This was the first Andhra Mahasab' WHERE chapter_slug = 'telangana-history-en-ch19-andhra-mahasabha';
UPDATE theory_content SET concepts_json = concepts_json || 'ha not held in a village, a samsthanam, or a taluk headquarters — instead it was convened in the Kishen Prasad Bahadur jagir near Hyderabad, reflecting the state''s growing tolerance toward the sabha by this stage.\n*   Konda Venkata Ranga Reddy, who was elected president here, was being groomed by Kottaal Venkataramireddy for future leadership. Encouraged by Hanumantha Rao, he had joined the Andhra Jana Sangham and was active in public-welfare work; before this, he had not been active as an \"Andhra\" figure specifically in the Hyderabad legislative assembly.\n*   He was regarded by both the public and the government as upright and impartial, though his outlook reflected a somewhat pronounced pro-Andhra regional bias, and he was proficient in Telugu and Urdu. He later went on to hold ministerial office after self-government and to become Deputy Chief Minister of Andhra Pradesh; a district was subsequently named after him (\"Rangareddy district\").\n*   **Fifth Andhra Mahila Sabha:** presided over by **Burgula Ananta Lakshmi Devi**, giving particular attention to farmers'' problems at this women''s session.\n*   The government''s attitude toward the Shadnagar sessions showed some hostility: it insisted the organizers advertise it as being held \"under government auspices\" and set up an exhibition of government departments at the venue, for which purpose a special structure was built at Shadnagar under the supervision of Vallури Basavaraju.\n*   This was V.B. Raju''s first participation in an Andhra Mahasabha; he was by then already an established, well-known engineer in Hyderabad, still young at the time.\n*   Because Shadnagar was close to Hyderabad, a large number of leaders and workers attended.\n*   The Sabha opposed the _matantarikarana_ (religious conversion) campaign undertaken by Bahadur Yar Jung; Konda Venkata Ranga Reddy and his co-workers personally visited households where people had converted to Islam to learn of the hardships faced by converts.\n*   The Shadnagar sabha also called for education for the people through their mother tongue, and demanded a total ban on liquor.", "free": false}, {"partNumber": 8, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p8", "partName": "Sixth Andhra Mahasabha — Nizamabad (1935)", "bodyMd": "By this stage the political climate was shifting: under the Government of India Act of 1935, elections had brought Congress governments to power in nine British Indian provinces, and this naturally influenced political currents within Hyderabad State. Muslims in the state were also pressing for reforms, and the government could not entirely refuse them; it appointed a reform committee under Diwan Bahadur S. Aravamudu Ayyangar.\n\nIt was against this changed backdrop that the sixth Andhra Mahasabha convened at **Nizamabad** under **Mandamula Narasimha Rao**.\n\n*   Narasimha Rao was the editor of the Urdu daily _Rayyat_, distinguished for its style and a paper that rendered great service to the Andhrodyamam. He was deeply affected by farmers'' problems, and whenever legislative measures were needed to address them, the government would bring in another individual to introduce the relevant bill in his place.\n*   He maintained friendly relations with Muslim leaders in the state. After self-government, his brother-in-law Burgula Ramakrishna Rao''s government appointed him chairman of the Land Commission, and he later became a minister after the formation of Andhra Pradesh.\n*   At Nizamabad, the presidency was, as usual, held by a state resident, and delegates resolved that they must act with a sense of responsibility toward the state. Provincial-style reforms were sought following the British Indian pattern, and resolutions were framed accordingly.\n*   Through this session the Andhra Mahasabha''s true character became clearer, and the aspirations and intentions of the Andhra people became more openly expressed; it also marked the point at which the movement acquired real political weight within the state.", "free": false}, {"partNumber": 9, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p9", "partName": "Seventh Andhra Mahasabha — Malkapuram (1938)", "bodyMd": "The seventh Andhra Mahasabha was held at Malkapuram in 1938 under **Mandumula Ramachandra Rao''s** presidency, at a time of acute land-revenue grievance in Telangana:\n\n*   In Telangana, land assessed as _tari_ (wet/irrigated) land was taxed at rates ranging from Rs. 15 to Rs. 22 per acre, compared with Rs. 5 to Rs. 10 per acre in British India.\n*   When Prakasam Pantulu became Revenue Minister in Madras, he reduced the tax rate there by roughly one-fourth (25%); the Sabha demanded that Telangana''s rates be reduced in line with the Madras pattern.\n*   On the occasion of the Nizam''s Silver Jubilee, the Diwan had granted an overall remission of Rs. 40 lakhs, of which the Sircilla region alone received Rs. 42 lakhs in remission. Special permission was required even to conduct personal (individual) inspection of the survey-settlement staff.\n*   The Sabha called for removing this discrepancy between the Diwan''s remission figures and the Sircilla-area figures.", "free": false}, {"partNumber": 10, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p10", "partName": "Eighth Andhra Mahasabha — Chilkuru (1941)", "bodyMd": "The eighth Andhra Mahasabha was held in 1941 at **Chilkuru** village, Huzurnagar taluk, Nalgonda district, under the young leader **Ravi Narayana Reddy**.\n\n*   Narayana Reddy was among the state''s first satyagrahis, and rose in politics as a young leader with socialist leanings within the State Congress. He holds a place in Telangana''s history from the movement''s beginning to its end, and served as a steadfast leader (_kanaka nilichina karthadhari_) throughout this struggle.\n*   At this session, the constitution was amended and the membership fee reduced from one rupee to four annas.\n*   After the eighth Mahasabha, a week-long campaign known as **\"Begar Week\"** was conducted, protesting forced/unpaid labour.\n*   From this point onward, the Andhra Mahasabha also began paying attention to Communist-organized programmes.\n*   **Mahila Sabha:** presided over by **Rangamma Obul Reddy**.", "free": false}, {"partNumber": 11, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p11", "partName": "Ninth Mahasabha — Dharmavaram (1942)", "bodyMd": "The ninth Andhra Mahasabha was held at **Dharmavaram**, Warangal district, in 1942, under **Madiraju Ramakoteswara Rao**.\n\n*   Communists and anti-Communists within the sabha openly debated their differing approaches to world affairs at this session, and it was here that the theme of the national-flag movement (_jatiyapataka udyamam_) first entered public discussion.\n*   This session was held two years after the eighth Mahasabha, with Mandumula Narasimha Rao presiding over its Mahila Sabha. Rangamma Obul Reddy again presided over the women''s session, which was noted for being the largest of the joint women''s sessions held alongside the Andhra Mahasabhas.\n*   By the Dharmavaram session, three factions had emerged within the Andhra Mahasabha: Congress-aligned moderates, Communists, and a middle group. Government recognition of the Andhra Mahasabha''s growing public support led to it being acknowledged as a major organization in the state.\n*   As the Andhra Mahasabha increasingly took on the character of a people''s organization (_prajasangha_), class divisions surfaced openly — landed-interest moderates on one side, and Communists championing farmers'' interests against them on the other, leading to friction between the two camps.", "free": false}, {"partNumber": 12, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p12", "partName": "Tenth Mahasabha — Hyderabad (1943)", "bodyMd": "The tenth Andhra Mahasabha was held in the state capital, Hyderabad, on 23–25 May 1943.\n\n*   The session was grandly organized at Reddy Hostel; Madapati Hanumantha Rao and his followers attended in large numbers, as did a significant contingent of Communist sympathizers.\n*   The presidential contest was between **Konda Venkata Ranga Reddy** and **Baddam Yellareddy**; the moderate candidate Konda Venkata Ranga Reddy won.\n*   Baddam Yellareddy, Arutla Lakshminarasimha Reddy, and Ravi Narayana Reddy were appointed as working-committee members. They were known as respected Communists and were treated with special regard.\n*   Because the session was held in Hyderabad, it gained added prominence; Sarojini Naidu, Raja Bahadur Venkataramareddy, Major M.J. Naidu, and several samsthana chiefs took part.\n*   The chief demand debated was the establishment of a form of \"responsible government\" in Hyderabad State. This session was a major turning point, since it marked the first time a clear rivalry over control of an organization arose openly between Communists and Congress-aligned members, with the Congress side winning a majority within the Andhra Mahasabha.\n*   In 1942, Communists had opposed the Quit India movement, branding it a \"movement against the people''s interest,\" which by then had already made them controversial at the all-India level.", "free": false}, {"partNumber": 13, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p13", "partName": "Subsequent Sessions (11th–13th) and the Moderate–Extremist Split", "bodyMd": "**Eleventh Mahasabha — Bhuvanagiri (1944):** Held on 27–28 May 1944 under **Ravi Narayana Reddy**. The influence of ideological factions (_chilika prabhavam_) was conspicuous at this session, and many who had been prominent leaders and workers since the start of the Andhrodyamam did not take part.\n\nNational, communal, and international issues were extensively debated, and the membership fee was reduced from four annas to one anna.\n\n**Twelfth Mahasabha — Madikonda (1945):** Held on 21–23 March 1945 in Madikonda, Warangal district, under **Mandumula Narasimha Rao**. Konda Venkata Ranga Reddy took particular interest in ensuring this session''s success.\n\n**Thirteenth Mahasabha — Kandi (1946):** Held on 10–12 May 1946 at Kandi, Medak district, under **Sardar Jamalapuram Keshava Rao**, a leading figure in the State Congress satyagraha movement and a committed nationalist. After this, no leader of comparable stature emerged again for the Khammam district Congress.\n\n**By 1946, the movement in Telangana — which had begun as a limited cultural movement (Andhrodyamam) — had transformed step by step into a revolutionary movement.** This thirteenth session was the last of its kind: the very first session had been held in Jogipet, Medak district, and, in a symbolic circle, the last was also held in Medak district, at Kandi.\n\nFollowing this session, moderate leaders within the Andhra Mahasabha moved into the Congress party, while the extremists joined the Communist Party. Until that time, the single major organization that had represented the Andhra people had been the Andhra Mahasabha alone.\n\n### Summary Table — Andhra Mahasabha Sessions (1930–1946)\n\n| No. | Year | Venue | President |\n|---|---|---|---|\n| 1 | 1930 | Jogipet | Suravaram Pratapa Reddy |\n| 2 | 1931 | Devarakonda | Burgula Ramakrishna Rao |\n| 3 | 1934 | Khammam Mettu | Pulijala Ranga Rao |\n| 4 | 1935 | Sircilla | Madapati Hanumantha Rao |\n| 5 | 1936 | Shadnagar | Konda Venkata Ranga Reddy |\n| 6 | 1935 | Nizamabad | Mandamula Narasimha Rao |\n| 7 | 1938 | Malkapuram | Mandumula Ramachandra Rao |\n| 8 | 1941 | Chilkuru | Ravi Narayana Reddy |\n| 9 | 1942 | Dharmavaram | Madiraju Ramakoteswara Rao |\n| 10 | 1943 | Hyderabad | Konda Venkata Ranga Reddy |\n| 11 | 1944 | Bhuvanagiri | Ravi Narayana Reddy |\n| 12 | 1945 | Madikonda | Mandumula Narasimha Rao |\n| 13 | 1946 | Kandi | Jamalapuram Keshava Rao |", "free": false}, {"partNumber": 14, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p14", "partName": "Women''s Participation — Andhra Mahila Sabhas", "bodyMd": "The Andhra Mahila Sabhas were held independently alongside each Andhra Mahasabha, functioning entirely without interference from the men''s sessions — the first all-Telangana women''s sabhas of their kind. They strengthened women''s organizational goals, worked for the upliftment of women, and helped awaken vitality and development among them.\n\nWomen who otherwise avoided public gatherings came forward enthusiastically to attend the Mahila Sabhas.\n\nGiven the low status of women''s rights across India at the time, these sabhas pursued whatever progressive change was practicable. They supported widow remarriage; opposed polygamy, child marriage, and prostitution; called for daughters to receive a share in parental property; and demanded representation for women in the legislature.\n\nThe patronage extended by the Andhra Mahasabha leaders and the freedom given to these sabhas were praiseworthy. However senior a leader, none was permitted to interfere in the discussions of the Mahila Sabhas, which were conducted with firm independence and free from disorderly disruption.\n\n**Presidents of the Andhra Mahila Sabhas, in order:** Nadimpalli Sundaramma; T. Varalakshmamma; Ellapragada Seetakumari; Madapati Manikyamma; Burgula Ananta Lakshmi Devi; Nandagiri Indira Devi; Yogya Sheela Devi; Rangamma Obul Reddy; Rangamma Obul Reddy; Nimmagadda Sathyavathi; Ellapragada Seetakumari.\n\nAt Sircilla (the fourth Mahasabha), the women''s session was held under Madapati Manikyamma; it was there that Ellapragada Seetakumari raised the idea of forming a separate \"Andhra Yuvathi Mandali\" (Andhra Young Women''s Association).", "free": false}, {"partNumber": 15, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p15", "partName": "Andhra Yuvathi Mandali", "bodyMd": "Following the suggestion raised at the Sircilla Andhra Mahila Sabha, Ellapragada Seetakumari met Burgula Ramakrishna Rao''s wife, Smt. Ananta Lakshmi Devi, and laid the groundwork for founding the Andhra Yuvathi Mandali. She then met further with the Rani of Gadwal, Adilakshmi Devi, and the three of them established the Andhra Yuvathi Mandali in 1935.\n\nThe Rani of Gadwal served as its president, Burgula Ananta Lakshmi Devi as vice-president, and Seetakumari as secretary. This was 15 years before Durgabai Deshmukh''s Hyderabad Andhra Mahila Sabha was founded.\n\n*   Later, accomplished Andhra women in the city were drawn onto its committee, including Illindala Saraswati Devi (treasurer) and Illindala Shyamala Devi, among other office-bearers.\n*   The Mandali began its activities soon after formation. The Gadwal Rani Adilakshmi Devi, using her special influence, arranged for shops on Reddy Hostel Road to be given rent-free to support the association''s work.\n*   A staff member was appointed to procure good books from the Sri Krishnadevaraya Andhra Bhasha Nilayam library and elsewhere, which were sent out weekly to women who wished to read. Through this the Mandali promoted language development and dispelled ignorance among wom' WHERE chapter_slug = 'telangana-history-en-ch19-andhra-mahasabha';
UPDATE theory_content SET concepts_json = concepts_json || 'en.\n*   The Andhra Yuvathi Mandali, founded in 1935, went on in 1952 to acquire its own premises through the efforts of the era''s leading figures, built the Andhra Yuvathi Mandali building, and opened a primary school there. This grew steadily and became a high school by 1954.\n*   In 1955 a child-development centre (Shishu Vikas Vihar) was added, followed by CMPF women''s hostels, a library, and a tailoring-training centre. The Mandali went on to expand into numerous festivals and literary gatherings, reaching a high level of distinction.", "free": false}, {"partNumber": 16, "conceptId": "telangana-history-en-ch19-andhra-mahasabha-p16", "partName": "State-Level Women''s Sabhas", "bodyMd": "Although Hyderabad State had a numerical majority of Telangana residents, Andhras had no representation in government employment or in high offices, nor was there any organizational framework guaranteeing this. New temples could not be built anywhere in the state, and repairs to existing ones required special permission. Public meetings and assemblies were barred under Gasthi Nishan-53 (Circular 53).\n\nFacing such restrictions, the Telugu people''s self-respect had to be asserted step by step. Women''s status was even more constrained, hedged with numerous further restrictions and limitations.\n\nIn 1916, Mrs. Cousins visited Hyderabad, at a time when the All India Women''s Conference had already been established in Delhi. In Hyderabad city, Smt. Sarojini Naidu, Lady Hamida Hyder, and Rustomji Sardarji, among others, founded a women''s association for education and social organization at this gathering, with Rajkumari Dhanraj Girji elected as its president.\n\n*   Sarojini Naidu was deeply engaged in national Indian politics; other women leaders organized sabhas focused on women''s education and social advancement.\n*   After the Nizam government''s Kotwal took over the running of this body, several appealing programmes followed. Membership, however, remained largely confined to the wives of officials and the wealthy rather than reaching ordinary women.\n*   In those days, the Nizam''s senior official Durru Shehvar Begum served as the association''s president and patron. Wives of British ministers such as Lady Tussaud and Lady Trench, along with Christian women workers such as Cornelius and Williams, also took part in its activities.\n*   Later, Rangamma Obul Reddy, Rani Saralamdevi, and Sundaramma also worked to bring about change in this body.\n\nAs the reform movement grew and the influence of the national movement spread, the women of Telangana came, gradually, to take their place within the wider national movement.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-ch19-andhra-mahasabha';
